import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Bibliometrics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/bibliometrics.md","filePath":"guide/bibliometrics.md","lastUpdated":1793111003000}'),o={name:"guide/bibliometrics.md"};function n(i,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="bibliometrics" tabindex="-1">Bibliometrics <a class="header-anchor" href="#bibliometrics" aria-label="Permalink to &quot;Bibliometrics&quot;">​</a></h1><p>Explore the metadata of a saved search in <strong>Bibliometrics</strong>. An analysis has its own title, history, and exports.</p><h2 id="create-an-analysis" tabindex="-1">Create an analysis <a class="header-anchor" href="#create-an-analysis" aria-label="Permalink to &quot;Create an analysis&quot;">​</a></h2><p>Choose a completed search, or use the analysis action from its results. PaperSeek saves an independent snapshot of the compact candidate metadata. Deleting the source search does not delete the analysis.</p><p>The input is the <strong>actually retrieved, deduplicated candidate corpus</strong>, including available citation-expansion candidates. It is not the source&#39;s reported total, the whole research field, or just the final relevance-ranked list. Search budgets still limit retrieval; LLM scoring still covers only its original subset. Creating an analysis does not score every paper, call a language model, or fetch missing metadata.</p><p>Older searches without this corpus artifact can only be analyzed from their saved final results. The interface labels this reduced scope explicitly. Re-running a search is necessary to obtain the broader corpus.</p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><table tabindex="0"><thead><tr><th>View</th><th>What it provides</th></tr></thead><tbody><tr><td>Overview</td><td>Publication years, venues, document types, authors, institutions, countries, citation coverage, and the scored subset</td></tr><tr><td>Venue rankings</td><td>CAS tiers and Top, JCR quartiles, CCF classes, and a table of ranked journals and conferences with their Impact Factor</td></tr><tr><td>Keywords</td><td>Native keywords or source categories, frequencies, and an optional co-occurrence network</td></tr><tr><td>Paper relations</td><td>Bibliographic coupling: papers connected by shared returned references</td></tr><tr><td>Data quality</td><td>Field coverage, missing values, scope, and source limitations</td></tr></tbody></table><p>Venue rankings label the whole analysed corpus, not only scored papers, from the <a href="./results#journal-rankings-and-conference-acceptance">ShowJCR tables</a> on this computer when the analysis is created. An analysis created before the tables were downloaded has no ranking labels; create it again from the same search. Only the JCR IF is an Impact Factor.</p><p>Missing citation counts remain unknown; an explicitly returned zero remains zero. Author and institution labels are not identity-disambiguated. Country counts describe returned affiliations, not researcher nationality. Keyword provenance matters: an OpenAlex concept or a Semantic Scholar field is not necessarily an author-supplied keyword.</p><h2 id="generate-a-network" tabindex="-1">Generate a network <a class="header-anchor" href="#generate-a-network" aria-label="Permalink to &quot;Generate a network&quot;">​</a></h2><p>Opening a network tab does not compute it. Choose thresholds and click <strong>Generate network</strong>. Parameters collapse after submission and can be reopened above the canvas. Search node labels, select a node to inspect its details, and use the group legend to interpret colors. The server caches completed results by parameters; layout runs in a browser worker. A failed layout offers a retry.</p><p>Co-occurrence connects terms appearing in the same paper. Bibliographic coupling connects papers sharing references. Network groups are connected components, not validated semantic topics. Neither relationship proves that a paper supports a written claim; use the review&#39;s <strong>Citation evidence</strong> for that purpose.</p><p>Networks display at most <strong>300 nodes and 2,000 edges</strong>. Sparse computation also has pair-work limits. A dense corpus can require a higher threshold or exclusion of very common references. Display truncation and omitted data are reported. Category summaries retain up to 100 categories; exports preserve the underlying compact corpus.</p><h2 id="history-and-export" tabindex="-1">History and export <a class="header-anchor" href="#history-and-export" aria-label="Permalink to &quot;History and export&quot;">​</a></h2><p>Choose <strong>Bibliometrics</strong> in the left sidebar to see <strong>Analyses</strong>. Click a record to reopen it, use the magnifying glass beside the heading to search, or choose <strong>All</strong> for the full list. Each row in that list has a record menu for rename, export, and delete. Renaming changes the display title, not the source query.</p><p>CSV exports one row per corpus paper. JSON includes the corpus and scope metadata. These exports differ from search exports, which contain the final result set. Analysis deletion removes its snapshots and cached networks while leaving the source search and reviews intact.</p><h2 id="interpret-results-carefully" tabindex="-1">Interpret results carefully <a class="header-anchor" href="#interpret-results-carefully" aria-label="Permalink to &quot;Interpret results carefully&quot;">​</a></h2><p>This is preliminary bibliometric exploration of one bounded search. Source coverage, missing reference lists, name variants, and query selection affect distributions and networks. It is not a substitute for a reproducible multi-database systematic search or specialist bibliometric validation.</p>',19)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
